const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'฿'+Number(n||0).toLocaleString('th-TH');
let state={products:[],stores:[],cart:[],orders:[],sales:[],images:{},categories:[],receipts:[],paymentAttempts:[]},tab='catalog',category='all',timer;
const dialog=$('#dialog');
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function modal(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;if(!dialog.open)dialog.showModal();}
$('#close').onclick=()=>dialog.close();
async function api(path,method='GET',body){const response=await fetch('/api/demo'+path,{method,credentials:'same-origin',headers:method==='GET'?{}:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:method==='GET'?undefined:JSON.stringify(body||{})});let data;try{data=await response.json();}catch{throw Error('เชื่อมต่อห้องทดลองไม่ได้ กรุณาลองอีกครั้ง');}if(!response.ok)throw Error(data.error||'ทำรายการจำลองไม่สำเร็จ');if(data.demo===true){state=data;render();}return data;}
async function act(el,fn){el.disabled=true;try{await fn();}catch(e){toast(e.message);}finally{el.disabled=false;}}
const product=id=>state.products.find(p=>p.id===id),photo=p=>state.images[p.image]||'',statusNames={awaiting_payment:'รอชำระจำลอง',paid_demo:'ชำระจำลองแล้ว',preparing:'ร้านกำลังเตรียม',ready:'พร้อมรับสินค้า',completed:'รับสินค้าสำเร็จ',cancelled:'ยกเลิกแล้ว'};
const label=s=>statusNames[s]||s;
function render(){document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===state.role));$('#role-status').textContent='DEMO · '+(state.role==='seller'?'บทบาทร้านค้า':'บทบาทผู้ซื้อ');const tabs=state.role==='seller'?[['sales','รายการขาย'],['sell','ลงขายจำลอง']]:[['catalog','เลือกซื้อสินค้า'],['cart',`ตะกร้า (${state.cart.length})`],['orders','คำสั่งซื้อของฉัน']];if(!tabs.some(t=>t[0]===tab))tab=tabs[0][0];$('#tabs').innerHTML=tabs.map(([id,title])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${title}</button>`).join('');if(tab==='catalog')renderCatalog();else if(tab==='cart')renderCart();else if(tab==='orders'||tab==='sales')renderOrders();else renderSell();}
function renderCatalog(){$('#content').innerHTML=`<div class="catalog-head"><div><h2>ของดี พร้อมเดินทางต่อ</h2><p>สินค้าสาธิตสำหรับทดลองซื้อ ไม่ใช่ประกาศจริง</p></div><select id="category" aria-label="หมวดหมู่">${state.categories.map(c=>`<option value="${esc(c.id)}" ${category===c.id?'selected':''}>${esc(c.label)}</option>`).join('')}</select></div><div class="grid">${state.products.filter(p=>p.mode!=='auction'&&(category==='all'||p.category===category)).map(p=>`<article class="card"><a href="#" data-detail="${esc(p.id)}"><img src="${esc(photo(p))}" alt="${esc(p.title)}" loading="lazy"></a><div class="card-body"><span class="pill demo">สินค้าสาธิต</span><h3>${esc(p.title)}</h3><small>${esc(p.condition)} · ${esc(p.location)}</small><strong class="price">${money(p.price)}</strong><button data-add="${esc(p.id)}" ${p.status&&p.status!=='active'?'disabled':''}>${p.status&&p.status!=='active'?'ไม่พร้อมขาย':state.cart.includes(p.id)?'อยู่ในตะกร้าแล้ว':'เพิ่มลงตะกร้า'}</button></div></article>`).join('')||'<div class="empty">ยังไม่มีสินค้าในหมวดนี้</div>'}</div>`;$('#category').onchange=e=>{category=e.target.value;renderCatalog();};}
function detail(id){const p=product(id);if(!p)return;modal(p.title,`<img class="detail-image" src="${esc(photo(p))}" alt="${esc(p.title)}"><p>${esc(p.description)}</p><strong class="total">${money(p.price)}</strong><div class="notice">DEMO · ไม่มีสินค้าจริงหรือการจ่ายเงินจริง</div>${state.role==='buyer'?`<button class="primary" data-add="${esc(p.id)}" ${p.status&&p.status!=='active'?'disabled':''}>เพิ่มลงตะกร้า</button>`:''}`);}
function renderCart(){const items=state.cart.map(product).filter(Boolean);$('#content').innerHTML=`<h2>ตะกร้าทดลองของคุณ</h2>${items.length?items.map(p=>`<div class="cart-row"><img src="${esc(photo(p))}" alt="${esc(p.title)}"><div><h3>${esc(p.title)}</h3><strong>${money(p.price)}</strong></div><button class="text" data-remove="${esc(p.id)}">ลบ</button></div>`).join('')+`<div class="total"><span>ยอดสินค้าเบื้องต้น</span><strong>${money(items.reduce((n,p)=>n+p.price,0))}</strong></div><div class="notice">ยอดสุดท้ายจะตรวจสอบจากเซิร์ฟเวอร์ ไม่มีค่าส่งหรือการรับเงินจริง</div><button class="primary" id="create-order">สร้างคำสั่งซื้อจำลอง →</button>`:'<div class="empty"><h3>ยังไม่มีของในตะกร้า</h3><button data-tab="catalog">เลือกสินค้าสาธิต</button></div>'}`;const b=$('#create-order');if(b){const key=crypto.randomUUID();b.onclick=()=>act(b,async()=>{const r=await api('/orders','POST',{requestKey:key});tab='orders';render();const o=state.orders.find(x=>x.id===r.orderId)||state.orders[0];if(o)pay(o.id);});}}
function stepper(status){const order=['awaiting_payment','paid_demo','preparing','ready','completed'],position=order.indexOf(status);return `<ol class="steps">${['สั่งซื้อ','ชำระจำลอง','ร้านเตรียม','พร้อมรับ','รับแล้ว'].map((x,i)=>`<li class="${position>=i?'done':''}">${String(i+1).padStart(2,'0')} ${x}</li>`).join('')}</ol>`;}
const orderItems=o=>o.items||[];
function renderOrders(){const sales=tab==='sales',list=sales?state.sales:state.orders;$('#content').innerHTML=`<h2>${sales?'หลังร้าน · คำสั่งซื้อสาธิต':'ติดตามคำสั่งซื้อสาธิต'}</h2><div class="notice">${sales?'ทดลองเป็นร้านค้า: เมื่อผู้ซื้อชำระจำลองแล้ว กดเตรียมสินค้าและพร้อมรับ จากนั้นสลับเป็นผู้ซื้อเพื่อยืนยันรับ':'ชำระเงินแบบจำลอง → สลับเป็นร้านค้าเตรียมสินค้า → กลับมาเป็นผู้ซื้อเพื่อยืนยันรับ'}</div>${list.length?list.map(o=>`<article class="order"><div class="row"><strong class="order-id">${esc(o.id)}</strong><span class="pill">${esc(label(o.status))}</span></div>${stepper(o.status)}<p>${orderItems(o).map(i=>`${esc(i.title)} · ${money(i.price)}`).join('<br>')}</p><div class="total"><span>ยอดจากระบบ</span><strong>${money(o.total??o.subtotal)}</strong></div><div class="actions">${!sales&&o.status==='awaiting_payment'?`<button class="primary" data-pay="${esc(o.id)}">ชำระเงินจำลอง</button><button data-cancel="${esc(o.id)}">ยกเลิกจำลอง</button>`:''}${sales&&o.status==='paid_demo'?`<button class="primary" data-fulfill="${esc(o.id)}" data-status="preparing">เริ่มเตรียมสินค้า</button>`:''}${sales&&o.status==='preparing'?`<button class="primary" data-fulfill="${esc(o.id)}" data-status="ready">แจ้งพร้อมรับสินค้า</button>`:''}${!sales&&o.status==='ready'?`<button class="primary" data-receive="${esc(o.id)}">จำลองการรับสินค้า</button>`:''}${!['awaiting_payment','cancelled'].includes(o.status)?`<button data-receipt="${esc(o.id)}">ดูใบยืนยันจำลอง</button>`:''}</div></article>`).join(''):'<div class="empty"><h3>ยังไม่มีคำสั่งซื้อสาธิต</h3><p>สลับเป็นผู้ซื้อ เลือกสินค้า แล้วสร้างคำสั่งซื้อก่อน</p></div>'}`;}
function pay(id){const o=state.orders.find(o=>o.id===id);if(!o)return;modal('ชำระเงินจำลอง',`<div class="notice">DEMO · ไม่รับเงินจริง ไม่ต้องกรอกเลขบัตร CVV หรือบัญชีธนาคาร</div><div class="payment-art">DEMO ONLY<small>ไม่มี QR สำหรับโอนเงินจริง</small></div><div class="total"><span>ยอดชำระจำลอง</span><strong>${money(o.total)}</strong></div><label>เลือกวิธีจำลอง <select id="payment-method"><option value="qr_demo">QR จำลอง (ไม่มี QR ที่ใช้โอนได้)</option><option value="card_demo">บัตรจำลอง (ไม่กรอกข้อมูลบัตร)</option></select></label><p class="error" id="payment-error" role="alert"></p><div class="actions"><button class="primary" data-outcome="success" data-payment-order="${esc(id)}">จำลองชำระสำเร็จ</button><button data-outcome="declined" data-payment-order="${esc(id)}">จำลองชำระไม่ผ่าน</button></div>`);}
function receipt(id){const o=[...state.orders,...state.sales].find(o=>o.id===id);if(!o)return;const r=state.receipts.find(x=>x.orderId===id||x.order_id===id);modal('ใบยืนยันการชำระเงินจำลอง',`<article class="receipt"><span class="pill demo">DEMO · ไม่ใช่ใบกำกับภาษี</span><h3>Two-Hands</h3><strong>ใบยืนยันการชำระเงินจำลอง</strong><p class="order-id">คำสั่งซื้อ ${esc(id)}</p>${r?`<small>เลขอ้างอิง ${esc(r.id||r.number||'—')}</small><p>เวลาชำระจำลอง ${esc(new Date(r.at).toLocaleString('th-TH'))}<br>วิธีชำระ: ${r.method==='card_demo'?'บัตรจำลอง':'QR จำลอง'}</p>`:''}<p>${orderItems(o).map(i=>`${esc(i.title)} · ${money(i.price)}`).join('<br>')}</p><div class="total"><span>ยอดจำลองจากระบบ</span><strong>${money(r?.amount??r?.total??o.total??o.subtotal)}</strong></div><small>ใช้เพื่อการเรียนรู้เท่านั้น ไม่มีการรับหรือโอนเงินจริง ไม่ใช่หลักฐานชำระเงินจริง และไม่ใช่ใบกำกับภาษี</small></article>`);}
function renderSell(){$('#content').innerHTML=`<h2>ลงขายสินค้าสาธิต</h2><div class="notice">ใช้ข้อมูลสมมติและภาพที่จัดเตรียมไว้เท่านั้น สินค้านี้จะอยู่ใน session สาธิตของคุณ</div><form class="stack" id="sell-form"><label>ชื่อสินค้า<input name="title" required maxlength="90" placeholder="เช่น เก้าอี้มุมอ่านหนังสือ (สาธิต)"></label><div class="form-grid"><label>หมวดหมู่<select name="category">${state.categories.filter(c=>c.id!=='all').map(c=>`<option value="${esc(c.id)}">${esc(c.label)}</option>`).join('')}</select></label><label>สภาพ<select name="condition"><option>สภาพดีมาก</option><option>เหมือนใหม่</option><option>สภาพดี</option><option>มีตำหนิ</option></select></label></div><label>รายละเอียด<textarea name="description" required minlength="10" maxlength="1500" placeholder="รายละเอียดสมมติอย่างน้อย 10 ตัวอักษร"></textarea></label><div class="form-grid"><label>ราคา (บาท)<input name="price" type="number" min="1" max="10000000" step="1" required></label><label>พื้นที่สมมติ<input name="location" value="กรุงเทพฯ (สาธิต)" required maxlength="120"></label></div><label>ภาพจากคลังสาธิต<select name="image" id="sell-image">${Object.keys(state.images).map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('')}</select></label><img id="sell-preview" class="detail-image" alt="ภาพประกอบสินค้าสาธิต"><p class="error" role="alert"></p><button class="primary" type="submit">ลงขายจำลอง</button></form>`;const preview=()=>{$('#sell-preview').src=state.images[$('#sell-image').value];};$('#sell-image').onchange=preview;preview();$('#sell-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');act(b,async()=>{try{const data=Object.fromEntries(new FormData(f));data.price=Number(data.price);await api('/products','POST',data);toast('ลงขายสาธิตแล้ว สลับเป็นผู้ซื้อเพื่อดูสินค้า');tab='sales';render();}catch(err){f.querySelector('.error').textContent=err.message;}});};}
$('#reset').onclick=()=>{modal('เริ่มการสาธิตใหม่?',`<p>ล้างข้อมูลตะกร้า คำสั่งซื้อ การชำระเงินจำลอง และสินค้าที่เพิ่มใน session สาธิตนี้ ไม่มีผลกับเว็บจริง</p><form id="reset-form" class="stack"><label class="check"><input type="checkbox" required>ยืนยันเริ่มการทดลองใหม่</label><button class="orange" type="submit">ล้างและเริ่มใหม่</button></form>`);$('#reset-form').onsubmit=e=>{e.preventDefault();act(e.currentTarget.querySelector('button'),async()=>{await api('/reset','POST',{});tab='catalog';render();dialog.close();toast('เริ่มสาธิตใหม่แล้ว');});};};
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.detail){e.preventDefault();detail(el.dataset.detail);return;}if(el.dataset.tab){tab=el.dataset.tab;render();return;}if(el.dataset.pay){pay(el.dataset.pay);return;}if(el.dataset.receipt){receipt(el.dataset.receipt);return;}if(el.dataset.role){act(el,async()=>{await api('/role','POST',{role:el.dataset.role});dialog.close();});return;}if(el.dataset.add){act(el,async()=>{await api('/cart/'+encodeURIComponent(el.dataset.add),'PUT');toast('เพิ่มลงตะกร้าสาธิตแล้ว');});return;}if(el.dataset.remove){act(el,()=>api('/cart/'+encodeURIComponent(el.dataset.remove),'DELETE'));return;}if(el.dataset.paymentOrder){const method=$('#payment-method').value,outcome=el.dataset.outcome;act(el,async()=>{try{await api('/orders/'+encodeURIComponent(el.dataset.paymentOrder)+'/pay','POST',{method,outcome,requestKey:crypto.randomUUID()});if(outcome==='declined'){const error=$('#payment-error');if(error)error.textContent='จำลองชำระไม่ผ่าน ยังไม่มีการชำระเงิน ลองเลือกสำเร็จได้';}else{dialog.close();receipt(el.dataset.paymentOrder);toast('ชำระจำลองสำเร็จ สลับเป็นผู้ขายเพื่อเตรียมสินค้า');}}catch(err){$('#payment-error').textContent=err.message;}});return;}if(el.dataset.fulfill){act(el,()=>api('/orders/'+encodeURIComponent(el.dataset.fulfill)+'/fulfill','POST',{status:el.dataset.status}));return;}if(el.dataset.receive){modal('จำลองรับสินค้า',`<form class="stack" id="receive-form"><div class="notice">ขั้นตอนสาธิต ไม่มีการส่งมอบสินค้าจริง</div><label class="check"><input type="checkbox" required>ทดลองยืนยันว่าได้รับสินค้าจำลองแล้ว</label><button class="primary">ยืนยันรับจำลอง</button></form>`);$('#receive-form').onsubmit=e=>{e.preventDefault();act(e.currentTarget.querySelector('button'),async()=>{await api('/orders/'+encodeURIComponent(el.dataset.receive)+'/receive','POST',{});dialog.close();toast('การซื้อขายจำลองเสร็จสมบูรณ์');});};return;}if(el.dataset.cancel){act(el,()=>api('/orders/'+encodeURIComponent(el.dataset.cancel)+'/cancel','POST',{}));}});
api('/state').catch(e=>{$('#content').innerHTML=`<div class="empty"><p class="error">${esc(e.message)}</p><button id="retry">ลองเชื่อมต่ออีกครั้ง</button></div>`;$('#retry').onclick=()=>location.reload();});
